function Brand({ dark = false }: { dark?: boolean }) {
  return <Link href="/" className={`brand ${dark ? "brand-dark" : ""}`} data-testid="link-brand"><span className="brand-mark"><Sparkles size={15} /></span><span>prep<span className="brand-accent">master</span></span></Link>;
}

function Button({ children, variant = "primary", onClick, href, icon, disabled, className = "" }: { children: ReactNode; variant?: "primary" | "secondary" | "ghost" | "dark"; onClick?: () => void; href?: string; icon?: typeof ArrowRight; disabled?: boolean; className?: string }) {
  const content = <>{children}{icon && <Icon icon={icon} size={16} />}</>;
  if (href) return <Link href={href} className={`button button-${variant} ${className}`} data-testid={`link-${String(children).toLowerCase().replaceAll(" ", "-")}`}>{content}</Link>;
  return <button type="button" disabled={disabled} className={`button button-${variant} ${className}`} onClick={onClick} data-testid={`button-${String(children).toLowerCase().replaceAll(" ", "-")}`}>{content}</button>;
}

function ProgressBar({ value, tone = "coral" }: { value: number; tone?: string }) {
  return <div className={`progress-track progress-${tone}`}><span style={{ width: `${value}%` }} /></div>;
}

